print("Edition: signature")
rules = [("analyst", "read", "confidential", "DENY"), ("analyst", "read", "public", "ALLOW")]
def decide(role, action, resource):
    for r, a, res, effect in rules:
        if (r, a, res) == (role, action, resource):
            return effect + " by rule " + str((r, a, res))
    return "DENY by default"
for req in [("analyst", "read", "confidential"), ("analyst", "read", "public"), ("analyst", "read", "internal")]:
    print(req, "->", decide(*req))
print("RESULT explicit rules decide; anything unmatched denied by default")
